package pe.jamix.catalog.web;

import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

import org.jspecify.annotations.Nullable;
import org.springframework.stereotype.Component;

/**
 * Responsive sources for catalogue photos, exposed to the templates as {@code ${photos.srcset(url)}}.
 * A local photo {@code /img/<name>.jpeg} has WebP variants in {@code /img/opt/} (generated by
 * {@code npm run images}); any other URL (external, or not a photo) gets no srcset and the browser
 * keeps the original {@code src}.
 */
@Component("photos")
public class PhotoSources {

    /** Keep in sync with WIDTHS in scripts/optimize-images.mjs. */
    static final List<Integer> WIDTHS = List.of(480, 960);

    private static final Pattern LOCAL_PHOTO = Pattern.compile("^/img/([^/]+)\\.(?i:jpe?g|png)$");

    public @Nullable String srcset(@Nullable String imageUrl) {
        if (imageUrl == null) {
            return null;
        }
        Matcher local = LOCAL_PHOTO.matcher(imageUrl);
        if (!local.matches()) {
            return null;
        }
        String name = local.group(1);
        return WIDTHS.stream()
                .map(width -> "/img/opt/" + name + "-" + width + ".webp " + width + "w")
                .collect(Collectors.joining(", "));
    }
}
